head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92021.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function () {
};

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {void}
 * @hidden N
 */
scwin.init = async function () {
    // var parentWin = $c.win.getParent();
    const parentWin = $c.data.getParameter();
    scwin.vIsurCd = parentWin.isurCd;
    await scwin.listSync();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Dscl_onclick
 * @description 안내문작성 버튼
 * @returns {void}
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function () {
    try {
        await $c.win.alert("공시안내문");
        // scwin.fn_dscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92021.btn_Dscl_onclick" });
    }
};

/**
 * @method
 * @name grd_IssRecv_oncellclick
 * @description 상장내역 목록 클릭
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_IssRecv_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetail(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92021.grd_IssRecv_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function () {

    dma_selectCertHistListReq.set("isurCd", scwin.vIsurCd); // 발행회사
    const sbmOptions = {
        id: "sbm_selectCertHistList",
        action: "/api/listing/lstproc/stock/issuance-manage/stk-isu-action/select-cert-hist-list",
        method: "get",
        ref: "dma_selectCertHistListReq",
        target: "dlt_selectCertHistListRes=body",
        // submitDoneHandler : scwin.sbm_listCodeValue_submitdone,
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name openDetail
 * @description 상세 내역
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function (row) {

    dma_selectIssHistListReq.set("isurCd", scwin.vIsurCd); // 발행회사
    dma_selectIssHistListReq.set("listMethdTpCd", dlt_selectCertHistListRes.getCellData(row, "listMethdTpCd")); // 상장방법구분코드
    dma_selectIssHistListReq.set("listDd", dlt_selectCertHistListRes.getCellData(row, "listDd")); // 상장일
    dma_selectIssHistListReq.set("stkIsuRsnCd", dlt_selectCertHistListRes.getCellData(row, "stkIsuRsnCd")); // 발행사유코드
    const sbmOptions = {
        id: "sbm_selectIssHistList",
        action: "/api/listing/lstproc/stock/issuance-manage/stk-isu-action/select-iss-hist-list",
        method: "get",
        ref: "dma_selectIssHistListReq",
        target: "dlt_selectIssHistListRes=body",
        // submitDoneHandler : scwin.sbm_listCodeValue_submitdone,
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions);
    tbx_IssListTotalCnt.setValue(dlt_selectIssHistListRes.getRowCount());
};

