/**
 * @method
 * @name dscl
 * @description 공시안내문
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function () {
    // TODO Stage2: 공시안내문 작성(ULDSTF92024 팝업) 은 Stage 2 보류 — ① 사유코드→상장업무구분(rsnKey) TO-BE 데이터 수신, ② DIV_IDX_* 상수·js_market 은 상장공통($c.lc) 미반입,
    // ③ 공시 마스터/상세 조회(/Listing.do) 는 REST 전환 전, ④ getPar/setPar 참조채움 계약·copyDataList 는 팝업 전환본 확인 후 확정. btn_Dscl_onclick 은 호출 보류 중.
    // ⑤ 대상 DataList dts_DsclMst/dts_DsclDtl/dts_DsclMst_Eng/dts_DsclDtl_Eng/dlt_selectIssHistListRes_Eng 는 dataCollection 미선언(호출 시 ReferenceError — 625 사유 분기는 지금도 도달),
    // ⑥ 원본 조회 파라미터(method=searchIsuIssDsclList&DIV_IDX=…&ISUR_CD&listDd[&GUBUN_CD&listMethdTpCd]) 는 규칙 12 전환에서 탈락 — REST 재구성 시 vListDD/vRsnCd/vMethdTpCd 로 복원.
    const vRsnCd = dlt_selectCertHistListRes.getCellData(dlt_selectCertHistListRes.getRowPosition(), "stkIsuRsnCd");
    const vListDD = dlt_selectCertHistListRes.getCellData(dlt_selectCertHistListRes.getRowPosition(), "listDd");
    const vMethdTpCd = dlt_selectCertHistListRes.getCellData(dlt_selectCertHistListRes.getRowPosition(), "listMethdTpCd");

    // var vBzProcsNo = dlt_selectIssHistListRes.NameString(dlt_selectIssHistListRes.RowPosition, "bzProcsNo");
    let vBzProcsNo = "";
    for (let i = 0; i < dlt_selectIssHistListRes.getRowCount(); i++) {
        vBzProcsNo = vBzProcsNo + (vBzProcsNo === "" ? "" : ",") + dlt_selectIssHistListRes.getCellData(i, "bzProcsNo");
    }
    if (vRsnCd === "" || vBzProcsNo === "") {
        await $c.win.alert($c.data.getMessage("com_req_select", "대상"));
        return;
    }
    /*
    if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
        alert(getMessageParam("MSG-0022", ""));
        return ;
    }
    alert("vRsnCd."+vRsnCd)
    alert("vListDD."+vListDD)
    alert("vBzProcsNo."+vBzProcsNo)
     */
    let rsnKey = ""; // TODO Stage2: AS-IS fn_getRsnCse(사유코드→상장업무구분) 는 TO-BE 데이터로 수신 예정 — 수신 키 확정 후 대입
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;

    // 우선주의보통주전환사유 변경상장,추가상장 둘다 존재(2017.05.18)
    if (vRsnCd === '625') {
        if (vMethdTpCd === '2') {
            // 추가상장
            rsnKey = '130';
        } else if (vMethdTpCd === '3') {
            // 변경상장
            rsnKey = '141';
        }
    }

    // alert("발행사유코드 -->"+rsnKey + " vRsnCd:" + vRsnCd);

    if (rsnKey === "148") {
        // 상호변경
        const sbmOptions = {
            id : "sbm_dts_DsclMst",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /* 2009.05.22 영문공시 추가 */
        const sbmOptions2 = {
            id : "sbm_dts_DsclMst_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        let dBzProcsNo = vBzProcsNo;
        for (let i = 0; i < dts_DsclMst.getRowCount(); i++) {
            dBzProcsNo = dBzProcsNo + (dBzProcsNo === "" ? "" : ",") + dts_DsclMst.getCellData(i, "bzProcsNo");
        }
        /*
        fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            arr[0] = "70765";
            arr[1] = vBzProcsNo;
            arr[2] = vIsurCd;
            //copyDataSet( dts_Delistdetail , param_dts_isu) ;
            copyDataSet( dts_DsclMst, param_dts_mst) ;
            copyDataSet( dlt_selectIssHistListRes, param_dts2) ;
            return arr.length;
        }
         */
        // fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng) {
        scwin.getPar = function (arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
            if (js_market === "2") {
                arr[0] = "70765";
            } else {
                // 코넥스
                arr[0] = "32005";
            }
            arr[1] = dBzProcsNo;
            arr[2] = scwin.vIsurCd;
            scwin.copyDataList(dts_DsclMst, param_dts_mst);
            scwin.copyDataList(dlt_selectIssHistListRes, param_dts2);
            scwin.copyDataList(dts_DsclMst_Eng, param_dts_mst_eng);
            scwin.copyDataList(dlt_selectIssHistListRes_Eng, param_dts_dtl_eng);
            return arr.length;
        };
    } else if (rsnKey === "141A") {
        // 액면변경
        const sbmOptions = {
            id : "sbm_dts_DsclMst",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_DsclDtl",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclDtl=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /* 2009.06.03 영문공시 추가 */
        const sbmOptions3 = {
            id : "sbm_dts_DsclMst_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions4 = {
            id : "sbm_dts_DsclDtl_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclDtl_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
        // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /*
        fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            arr[0] = "70764";
            arr[1] = vBzProcsNo ;
            arr[2] = vIsurCd ;
            //copyDataSet( dts_Delistdetail , param_dts_isu) ;
            copyDataSet( dts_DsclMst, param_dts_mst) ;
            copyDataSet( dts_DsclDtl, param_dts2) ;
            return arr.length;
        }
         */
        // fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng, param_dts_dtl_eng) {
        scwin.getPar = function (arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
            if (js_market === "2") {
                arr[0] = "70764";
            } else {
                arr[0] = "32006";
            }
            arr[1] = vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            scwin.copyDataList(dts_DsclMst, param_dts_mst);
            scwin.copyDataList(dts_DsclDtl, param_dts2);
            scwin.copyDataList(dts_DsclMst_Eng, param_dts_mst_eng);
            scwin.copyDataList(dts_DsclDtl_Eng, param_dts_dtl_eng);
            return arr.length;
        };
    } else if (rsnKey === "141" || rsnKey === "130") {
        // 변경상장 141, 추가상장 130
        const sbmOptions = {
            id : "sbm_dts_DsclMst",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_DsclDtl",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclDtl=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /* 2009.06.03 영문공시 추가 */
        const sbmOptions3 = {
            id : "sbm_dts_DsclMst_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions4 = {
            id : "sbm_dts_DsclDtl_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclDtl_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
        // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        if (rsnKey === "141") {
            /*
            fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
                arr[0] = "70763";
                arr[1] = vBzProcsNo ;
                arr[2] = vIsurCd ;
                //copyDataSet( dts_Delistdetail , param_dts_isu) ;
                copyDataSet( dts_DsclMst, param_dts_mst) ;
                copyDataSet( dts_DsclDtl, param_dts2) ;
                return arr.length;
            }
             */
            // fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng, param_dts_dtl_eng) {
            scwin.getPar = function (arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
                if (js_market === "2") {
                    arr[0] = "70763";
                } else {
                    arr[0] = "32004"; // 코넥스 변경상장

                }
                arr[1] = vBzProcsNo;
                arr[2] = scwin.vIsurCd;
                scwin.copyDataList(dts_DsclMst, param_dts_mst);
                scwin.copyDataList(dts_DsclDtl, param_dts2);
                scwin.copyDataList(dts_DsclMst_Eng, param_dts_mst_eng);
                scwin.copyDataList(dts_DsclDtl_Eng, param_dts_dtl_eng);
                return arr.length;
            };
        } else if (rsnKey === "130") {
            /*
            fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
                arr[0] = "70791";
                arr[1] = vBzProcsNo ;
                arr[2] = vIsurCd ;
                //copyDataSet( dts_Delistdetail , param_dts_isu) ;
                copyDataSet( dts_DsclMst, param_dts_mst) ;
                copyDataSet( dts_DsclDtl, param_dts2) ;
                return arr.length;
            }
             */
            // fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3,  param_dts_mst_eng, param_dts_dtl_eng) {
            scwin.getPar = function (arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
                if (js_market === "2") {
                    arr[0] = "70791";
                } else {
                    arr[0] = "32003"; // 코넥스 추가상장

                }
                arr[1] = vBzProcsNo;
                arr[2] = scwin.vIsurCd;
                scwin.copyDataList(dts_DsclMst, param_dts_mst);
                scwin.copyDataList(dts_DsclDtl, param_dts2);
                scwin.copyDataList(dts_DsclMst_Eng, param_dts_mst_eng);
                scwin.copyDataList(dts_DsclDtl_Eng, param_dts_dtl_eng);
                return arr.length;
            };
        }
        /* 2009.05.22 영문공시 추가 끝 */
        /* 2009.07.01 영문공시 추가 - 추가상장(종목) : 국문,영문 */
    } else if (rsnKey === "100B") {
        // 추가상장
        // alert("추가상장(종목)");
        const sbmOptions = {
            id : "sbm_dts_DsclMst",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 영문
        const sbmOptions2 = {
            id : "sbm_dts_DsclMst_Eng",
            action : "/Listing.do",
            ref : "",
            target : "dts_DsclMst_Eng=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        scwin.getPar = function (arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_dtl_all_eng, param_dts_rel_eng) {
            if (js_market === "2") {
                arr[0] = "70762";
            } else {
                arr[0] = "32013"; // 코넥스 추가상장(종목)

            }
            arr[1] = vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            scwin.copyDataList(dts_DsclMst, param_dts_mst);
            scwin.copyDataList(dts_DsclDtl, param_dts2);
            scwin.copyDataList(dts_DsclMst_Eng, param_dts_mst_eng);
            scwin.copyDataList(dts_DsclDtl_Eng, param_dts_dtl_eng);
            // alert(dts_DsclMst_Eng.Text);
            return arr.length;
        };
    }

    // alert (dts_DsclMst.Text);
    // alert (dts_DsclDtl.Text);

    scwin.setPar = function (arr) {

    };
    const wth = 745 + 5;
    const hgt = 795 + 30;
    const pt = $c.fil.getModalCenterPos(window, wth, hgt);
    // await $c.win.openPopup 함수로 전환 필요 : await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    // frame.CreateDialogFrame("ULDSTF92024_EN", "/listingcommon/ULDSTF92024_EN.gfm", "영문공시안내문작성", pt.x, pt.y, wth, hgt, "window");

    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name copyDataList
 * @description 원본 DataList 전체 행을 대상 DataList 로 복사(대상 기존 행 삭제) — AS-IS 공통 CopyDataSet(Gauce ImportData/ExportData) 의 WebSquare 대체 구현(화면 로컬)
 * @param {*} src 원본 DataList
 * @param {*} dst 대상 DataList
 * @returns {void}
 * @hidden N
 */
scwin.copyDataList = function (src, dst) {
    if (!src || !dst) {
        return;
    }
    dst.removeAll();
    dst.setJSON(src.getAllJSON());
};
